css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::before { content: ''; position: absolute; inset: 22%; border-radius: 50%; border: 1px dashed color-mix(in srgb, var(--accent-2) 40%, transparent); }
.loader span { position: absolute; top: 50%; left: 50%; width: 0; height: 0; border-left: calc(var(--loader-size) * .18) solid var(--accent); border-top: calc(var(--loader-size) * .1) solid transparent; border-bottom: calc(var(--loader-size) * .1) solid transparent; margin: calc(var(--loader-size) * -.1) 0 0 calc(var(--loader-size) * -.09); animation: fly calc(var(--loader-speed) * 3) linear infinite; }
@keyframes fly { from { transform: rotate(0deg) translateX(calc(var(--loader-size) * .3)) rotate(115deg); } to { transform: rotate(360deg) translateX(calc(var(--loader-size) * .3)) rotate(115deg); } }
